import type { LegacyIoMappingResponse, LegacyIoRow } from "@pantin/core";
import { describeIoProblem, readFolderIo } from "./io-folder.ts";
import { readFolderDocument } from "./validate-folder.ts";

// `pantin gvl <folder>` (ADR 0045 point 9): the CODESYS global variable list
// of a valid mapping. No AT addresses: CODESYS assigns %I/%Q addresses in the
// device tree, where the channels are mapped to these variables.

const HEADER = [
  '// Generated by "pantin gvl" from io.csv and io-modules.json: do not edit it,',
  "// change the mapping and generate it again.",
  "//",
  "// WARNING (ADR 0046 point 10): a PLC trusts Pantin's feedback. The PLC under",
  "// test must never drive live outputs at the same time: use a SoftPLC, or a",
  "// controller with its field I/O disconnected.",
];

function declaration(row: LegacyIoRow): string {
  return `  ${row.variable} : ${row.ioType}; // ${row.module} ${row.zone} ${row.address}, ${row.tag}`;
}

/** The text of the GVL for the rows of a valid mapping. */
function renderGvl(rows: readonly LegacyIoRow[]): string {
  return [...HEADER, "VAR_GLOBAL", ...rows.map(declaration), "END_VAR", ""].join("\n");
}

export type GvlResult = { exitCode: number; stdout: string; errors: string[] };

function refusal(answer: LegacyIoMappingResponse): string[] {
  if (answer.status === "missing") {
    return ['No io.csv in this folder: run "pantin io init <folder>" first.'];
  }
  return [
    "The mapping is invalid, so no GVL is generated:",
    ...answer.problems.map(describeIoProblem),
  ];
}

export async function generateGvl(folder: string): Promise<GvlResult> {
  const read = await readFolderDocument(folder);
  if ("problems" in read) {
    return { exitCode: 1, stdout: "", errors: read.problems };
  }
  const answer = await readFolderIo(folder, read.document);
  if (answer.status !== "valid") {
    return { exitCode: 1, stdout: "", errors: refusal(answer) };
  }
  const errors =
    answer.unmappedTags.length === 0
      ? []
      : [`note: ${answer.unmappedTags.length} tag(s) are not mapped and not in the GVL.`];
  return { exitCode: 0, stdout: renderGvl(answer.rows), errors };
}
